$page_subtitle=$focus.' · menu dan data dibatasi oleh role serta konteks kepemilikan.';include __DIR__.'/includes/header.php';?><div class="grid cards"><?php foreach($stats as $s):?><div class="card stat"><div class="icon"><?=h($s[2])?></div><div class="num"><?=is_float($s[1])?'Rp '.number_format($s[1],0,',','.'):number_format($s[1])?></div><div class="label"><?=h($s[0])?></div><div class="hint"><?=h($s[3])?></div></div><?php endforeach;?></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-header"><div><h3 class="section-title">Recent Activity</h3><p class="section-subtitle">Hanya aktivitas relevan yang aman ditampilkan ke role ini.</p></div></div><div class="table-wrap"><table><?php if($role==='admin'):?><tr><th>Role</th><th>Users</th></tr><?php foreach($recent as $r):?><tr><td><?=h(role_label($r['role']))?></td><td><?=h((string)$r['jumlah'])?></td></tr><?php endforeach;?><?php elseif(in_array($role,['doctor'],true)):?><tr><th>Queue</th><th>Pasien</th><th>Waktu</th><th>Status</th></tr><?php foreach($recent as $r):?><tr><td>—</td><td><?=h($r['patient'])?><br><span class="mini"><?=h($r['mrn'])?></span></td><td><?=h(date('d/m H:i',strtotime($r['appointment_date'])))?></td><td><?=h($r['status'])?></td></tr><?php endforeach;?><?php elseif(in_array($role,['nurse','registration'],true)):?><tr><th>Pasien</th><th>Waktu</th><th>Status</th></tr><?php foreach($recent as $r):?><tr><td><?=h($r['name'])?><br><span class="mini"><?=h($r['mrn']??'')?></span></td><td><?=h(date('d/m H:i',strtotime($r[$role==='nurse'?'appointment_date':'registration_date'])))?></td><td><?=h($r['status'])?></td></tr><?php endforeach;?><?php elseif(in_array($role,['laboratory','radiology'],true)):?><tr><th>Pasien</th><th>Order</th><th>Priority</th><th>Status</th></tr><?php foreach($recent as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['order_name'])?></td><td><?=h(strtoupper($r['priority']))?></td><td><?=h($r['status'])?></td></tr><?php endforeach;?><?php elseif(in